type applicationResolveInput struct{ProjectID string `json:"projectId"`;WorkloadTypeID string `json:"workloadTypeId"`;TraitIDs []string `json:"traitIds"`;ObservedNativeCapabilities []string `json:"observedNativeCapabilities"`}
func(s *Server)resolveApplicationPlatformComposition(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};var in applicationResolveInput;if err:=decodeJSON(w,r,&in);err!=nil{writeError(w,400,"INVALID_REQUEST",err.Error());return};if !s.applicationProjectRead(w,r,in.ProjectID){return};wt,err:=st.GetWorkloadType(r.Context(),in.WorkloadTypeID);if err!=nil||wt.ProjectID!=strings.TrimSpace(in.ProjectID){if err==nil{err=controlplane.ErrNotFound};writeStoreError(w,err);return};traits:=[]controlplane.CapabilityTrait{};for _,id:=range in.TraitIDs{v,e:=st.GetCapabilityTrait(r.Context(),id);if e!=nil||v.ProjectID!=wt.ProjectID{if e==nil{e=controlplane.ErrNotFound};writeStoreError(w,e);return};traits=append(traits,v)};out,err:=controlplane.ResolveWorkloadComposition(wt,traits,in.ObservedNativeCapabilities);if err!=nil{writeStoreError(w,err);return};writeJSON(w,200,out)}

func(s *Server)createApplicationRelease(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};var in controlplane.ApplicationReleaseCreateRequest;if err:=decodeJSON(w,r,&in);err!=nil{writeError(w,400,"INVALID_REQUEST",err.Error());return};actor,ok:=s.applicationProjectWrite(w,r,in.ProjectID);if !ok{return};v,err:=st.CreateApplicationRelease(r.Context(),in,actor);if err!=nil{writeStoreError(w,err);return};writeJSON(w,201,v)}
func(s *Server)getApplicationRelease(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};v,err:=st.GetApplicationRelease(r.Context(),r.PathValue("id"));if err!=nil{writeStoreError(w,err);return};if !s.applicationProjectRead(w,r,v.ProjectID){return};writeJSON(w,200,v)}
func(s *Server)listApplicationReleases(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};pid:=strings.TrimSpace(r.URL.Query().Get("projectId"));if pid!=""&&!s.applicationProjectRead(w,r,pid){return};v,err:=st.ListApplicationReleases(r.Context(),pid);if err!=nil{writeStoreError(w,err);return};allowed,all,err:=s.accessibleProjectSet(r);if err!=nil{writeStoreError(w,err);return};v=filterProjectScoped(v,allowed,all,func(x controlplane.ApplicationRelease)string{return x.ProjectID});writeJSON(w,200,v)}

func(s *Server)createEnvironmentBinding(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};var in controlplane.EnvironmentBindingCreateRequest;if err:=decodeJSON(w,r,&in);err!=nil{writeError(w,400,"INVALID_REQUEST",err.Error());return};release,err:=st.GetApplicationRelease(r.Context(),in.ReleaseID);if err!=nil{writeStoreError(w,err);return};actor,ok:=s.applicationProjectWrite(w,r,release.ProjectID);if !ok{return};v,err:=st.CreateEnvironmentBinding(r.Context(),in,actor);if err!=nil{writeStoreError(w,err);return};writeJSON(w,201,v)}
