func(s *Server)listEnvironmentBindings(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};pid:=strings.TrimSpace(r.URL.Query().Get("projectId"));if pid!=""&&!s.applicationProjectRead(w,r,pid){return};v,err:=st.ListEnvironmentBindings(r.Context(),pid);if err!=nil{writeStoreError(w,err);return};allowed,all,err:=s.accessibleProjectSet(r);if err!=nil{writeStoreError(w,err);return};v=filterProjectScoped(v,allowed,all,func(x controlplane.EnvironmentBinding)string{return x.ProjectID});writeJSON(w,200,v)}
func(s *Server)promoteEnvironmentBinding(w http.ResponseWriter,r *http.Request){st,ok:=s.applicationPlatformAuthority(w);if !ok{return};current,err:=st.GetEnvironmentBinding(r.Context(),r.PathValue("id"));if err!=nil{writeStoreError(w,err);return};actor,ok:=s.applicationProjectWrite(w,r,current.ProjectID);if !ok{return};expected,err:=parseExpectedRevision(r);if err!=nil{writeError(w,http.StatusPreconditionRequired,"EXPECTED_REVISION_REQUIRED",err.Error());return};var in controlplane.EnvironmentBindingPromotionRequest;if err=decodeJSON(w,r,&in);err!=nil{writeError(w,400,"INVALID_REQUEST",err.Error());return};v,err:=st.PromoteEnvironmentBinding(r.Context(),current.ID,expected,in,actor);if err!=nil{writeStoreError(w,err);return};setRevisionETag(w,v.Revision);writeJSON(w,200,v)}
